(async()=>{
 const s=ms=>new Promise(r=>setTimeout(r,ms));
 const log=[];
 for (const t of ['run_start','room_enter','room_cleared','reward_offer','draft_taken','draft_declined','path_offer','path_chosen','room_transition','shop_open','shop_purchase','shop_close','glint_gain','run_end','boss_spawn','boss_adds','reward_forfeited'])
   __echoes.on(t,(e)=>log.push(e));
 __echoes.cmd('startRun'); await s(150);
 const paths=[];
 for(let g=0; g<80; g++){
   const v=__echoes.cmd('runState');
   if(v.phase==='victory'||v.phase==='defeat') break;
   if(v.phase==='combat'&&v.room===8){ __echoes.cmd('killBoss'); await s(100); __echoes.cmd('killAllEnemies'); await s(300); }
   else if(v.phase==='combat'){ __echoes.cmd('clearRoom'); await s(140); }
   else if(v.phase==='reward'){ __echoes.cmd('draftTake'); await s(140); __echoes.cmd('closeSocket'); await s(60); }
   else if(v.phase==='path'){ paths.push(v.path.options.map(o=>o.win+'/'+o.reward).join(' | ')+' free='+v.path.freeSkillSlots); __echoes.cmd('pathChoose', g%2); await s(430); }
   else if(v.phase==='shop'){ __echoes.cmd('shopBuy',0); await s(120); __echoes.cmd('shopAdvance'); await s(430); }
   else if(v.phase==='fade'){ await s(180); }
   else { await s(120); }
 }
 const v=__echoes.cmd('runState');
 return { phase:v.phase, summary:v.summary, paths,
  events: log.map(e=>e.type+(e.index?':r'+e.index:'')+(e.mode?':'+e.mode:'')+(e.promised?':p='+e.promised:'')+(e.type==='reward_offer'?'>'+e.type2:'')).join(' '),
  offers: log.filter(e=>e.type==='reward_offer').map(e=>'r'+e.room+' promised='+e.promised+' got='+e.type+' sub='+e.substituted),
  rooms: log.filter(e=>e.type==='room_enter').map(e=>'r'+e.index+':'+e.mode) };
})()
